// Custom sampler stubs (mapped to noise texture)
#define sampler_pw_noise_lq sampler_noise_lq
#define sat clamp01
sampler sampler_pw_noise_lq;
#define snh sampler_noise_hq
float d, z, radi, mask, ncity, ncity2, struc;
vec2 uv1, uv2, uv3, uvc;
const int anz = 18;
const vec2 pix = (vec2(1.0)/uTexSize) * 2.0;
vec3 Get1 (vec2 uvi, float par)
{return mix(GetBlur2(uvi) * 2.0, GetBlur1(uvi), par);}
float noise2 (vec2 uvi, float t) {vec3 tmp = 1; float s = 4; ;
for (int n = 1; n <= 2; n +=1 ) {uvi.y-=t*.05; tmp += texture(snh,uvi*s); s*=2;}
return tmp;}
float pwnoise (vec2 uvi, float t) {vec3 tmp = 1; float s = 1; ;
for (int n = 1; n <= 3; n +=1 ) {tmp += texture(sampler_pw_noise_lq,uvi*s)/s; s*=2.5;}
return (tmp);}
ret += (2.0 * shine2+ mix(GetPixel(uv),2.0 * GetBlur1(uv).xy,1.0 * rad*rad))*.8;
ret += GetPixel((.5-uv) * 2.0+.5) * 1.0 * sat(1.0 - rad * 3.0)*q27;
}
