void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  uv1 = (uv-vec2(0.5,0.52))*uAspect.xy;
z = .1/(uv1.y);
uv2 = vec2 (uv1.x * 1.0, 1.0 )*z + vec2( 0.0 ,uTime / 8.0);
mask = sat(texture(snh,uv2*0.1).r * 8.0-6);
d  = (noise2(uv2-pix,+uTime)-noise2(uv2+pix,uTime)).r;
d*=d;
ret=mask*0.015*(z>0)*noise2(uv2, 0.0 );
//ret += sat(texture(snh, uv2*.02).r-.6)*(z<0)*.2;
uv2=fract(uv1*vec2(.8,.4)+vec2(.5,.5));
ret += d*GetBlur2(uv2)*(z>0) * 2.0;
ret += sat(1-2/z)*.04*(1.5+sin(3.0 * rad-uTime*0.1))*(2.0 + slow_roam_cos) ;
ncity = sat(16.0 * (uv1.y+.120)>pwnoise(uv.x / 8.0, 0.0 )) *sat(1-2/z);
ret-=ncity / 16.0;
ncity = sat(6.0 * (uv.y-.2)>pwnoise(uv.x / 12.0, 0.0 )) *sat(1-2/z) * (abs(uv1.x)>0.07);
ncity2= sat(6.0 * (uv.y-.2)>pwnoise(uv.x / 12.0-0.003*uv1.x, 0.0 )) * (abs(uv1.x)>0.07);
ret-=ncity / 2.0;
struc=sat(ncity-ncity2)*(pwnoise(1.5*uv, 0.0 )-.5);
ret+=.25*struc;  //  ORIG:  =.15*
ret+=struc*sat(1.0 - rad)*GetBlur1(.5)*0.5;
ret=sat(ret);
radi = 1;
vec3 shine2 = 0;
for (int n=1; n <= anz;  n++)
{
shine2 +=   1.0 * Get1((uv-.5)*radi+.5,radi)/anz;
radi -= .5/anz;
  fragColor = vec4(ret, 1.0);
}

